import unittest

from affine_cipher import decode, encode


class AffineCipherTests(unittest.TestCase):
    def test_encode_example(self):
        self.assertEqual(encode("test", 5, 7), "ybty")

    def test_decode_examples(self):
        self.assertEqual(decode("ybty", 5, 7), "test")
        self.assertEqual(decode("ybty", 11, 7), "lqul")
        self.assertEqual(
            decode("kqlfd jzvgy tpaet icdhm rtwly kqlon ubstx", 19, 13),
            "thequickbrownfoxjumpsoverthelazydog",
        )

    def test_grouping_and_digits(self):
        self.assertEqual(encode("Testing 1 2 3!", 5, 7), "qclla 1 2 3")
        self.assertEqual(decode("qclla 1 2 3", 5, 7), "testi123")

    def test_non_coprime_key_is_rejected(self):
        for operation in (encode, decode):
            with self.subTest(operation=operation.__name__):
                with self.assertRaisesRegex(ValueError, "coprime"):
                    operation("test", 18, 13)

    def test_negative_key_parameters(self):
        ciphertext = encode("affine", -5, -7)
        self.assertEqual(decode(ciphertext, -5, -7), "affine")


if __name__ == "__main__":
    unittest.main()

from math import gcd


_ALPHABET_SIZE = 26


def _validate_key(a):
    if gcd(a, _ALPHABET_SIZE) != 1:
        raise ValueError("a and m must be coprime.")


def encode(plain_text, a, b):
    """Encrypt text, grouping the resulting alphanumeric characters in fives."""
    _validate_key(a)
    encrypted = []
    for char in plain_text.lower():
        if "a" <= char <= "z":
            encrypted.append(chr((a * (ord(char) - ord("a")) + b) % 26 + ord("a")))
        elif char.isdigit():
            encrypted.append(char)
    joined = "".join(encrypted)
    return " ".join(joined[index:index + 5] for index in range(0, len(joined), 5))


def decode(ciphered_text, a, b):
    """Decrypt affine-cipher text, ignoring grouping spaces and preserving digits."""
    _validate_key(a)
    inverse = pow(a, -1, _ALPHABET_SIZE)
    decoded = []
    for char in ciphered_text.lower():
        if "a" <= char <= "z":
            decoded.append(chr((inverse * (ord(char) - ord("a") - b)) % 26 + ord("a")))
        elif char.isdigit():
            decoded.append(char)
    return "".join(decoded)

import unittest

from affine_cipher import decode, encode


class AffineCipherTests(unittest.TestCase):
    def test_encrypt_and_decode_examples(self):
        self.assertEqual(encode("test", 5, 7), "ybty")
        self.assertEqual(decode("ybty", 5, 7), "test")
        self.assertEqual(decode("ybty", 11, 7), "lqul")

    def test_long_ciphertext_and_grouping(self):
        self.assertEqual(
            decode("kqlfd jzvgy tpaet icdhm rtwly kqlon ubstx", 19, 13),
            "thequickbrownfoxjumpsoverthelazydog",
        )
        self.assertEqual(encode("The quick brown fox!", 5, 7), "ybtyz qvwbz")

    def test_digits_are_preserved(self):
        self.assertEqual(encode("a1b2", 5, 7), "h1m2")
        self.assertEqual(decode("h1m2", 5, 7), "a1b2")

