        for operation, text in ((encode, "test"), (decode, "ybty")):
            with self.subTest(operation=operation.__name__):
                with self.assertRaisesRegex(ValueError, "coprime"):
                    operation(text, 18, 13)

    def test_negative_and_large_keys(self):
        encrypted = encode("affine cipher", -5, 33)
        self.assertEqual(decode(encrypted, -5, 33), "affinecipher")


