from math import gcd


_ALPHABET = "abcdefghijklmnopqrstuvwxyz"


def _validate_key(a):
    if gcd(a, 26) != 1:
        raise ValueError("a and m must be coprime.")


def encode(plain_text, a, b):
    """Encode text with the affine cipher, grouping output in blocks of five."""
    _validate_key(a)
    encoded = []
    for char in plain_text.lower():
        if char in _ALPHABET:
            index = _ALPHABET.index(char)
            encoded.append(_ALPHABET[(a * index + b) % 26])
        elif char.isdigit():
            encoded.append(char)
    text = "".join(encoded)
    return " ".join(text[index:index + 5] for index in range(0, len(text), 5))


def decode(ciphered_text, a, b):
    """Decode affine-cipher text, ignoring spaces and punctuation."""
    _validate_key(a)
    inverse = pow(a, -1, 26)
    decoded = []
    for char in ciphered_text.lower():
        if char in _ALPHABET:
            index = _ALPHABET.index(char)
            decoded.append(_ALPHABET[(inverse * (index - b)) % 26])
        elif char.isdigit():
            decoded.append(char)
    return "".join(decoded)

