    def test_shorter_row_is_not_padded_on_the_right(self):
        self.assertEqual(transpose("ABC\nDE"), "AD\nBE\nC")

    def test_missing_cells_are_padded_on_the_left(self):
        self.assertEqual(transpose("AB\nDEF"), "AD\nBE\n F")

    def test_preserves_explicit_spaces_and_bottom_spaces(self):
        self.assertEqual(transpose("A \n B"), "A \n  ")

