def transpose(text):
    """Return the rows of *text* as columns, preserving meaningful spaces."""
    lines = text.split("\n")
    width = max((len(line) for line in lines), default=0)
    result = []

    for column in range(width):
        # Missing cells are padding. Keep padding before a later present cell,
        # but omit it from the right edge of the transposed row.
        cells = [line[column] if column < len(line) else None for line in lines]
        while cells and cells[-1] is None:
            cells.pop()
        result.append("".join(" " if cell is None else cell for cell in cells))

    return "\n".join(result)

