import unittest

from proverb import proverb


class ProverbTests(unittest.TestCase):
    def test_complete_rhyme(self):
        self.assertEqual(
            proverb("nail", "shoe", "horse", "rider", "message", "battle", "kingdom"),
            [
                "For want of a nail the shoe was lost.",
                "For want of a shoe the horse was lost.",
                "For want of a horse the rider was lost.",
                "For want of a rider the message was lost.",
                "For want of a message the battle was lost.",
                "For want of a battle the kingdom was lost.",
                "And all for the want of a nail.",
            ],
        )

    def test_qualifier_applies_to_final_verse(self):
        self.assertEqual(
            proverb("nail", "shoe", "horse", qualifier="horseshoe"),
            [
                "For want of a nail the shoe was lost.",
                "For want of a shoe the horse was lost.",
                "And all for the want of a horseshoe nail.",
            ],
        )

    def test_single_word(self):
        self.assertEqual(proverb("seed"), ["And all for the want of a seed."])

    def test_empty_input(self):
        self.assertEqual(proverb(), [])

    def test_list_argument_supported(self):
        self.assertEqual(
            proverb(["one", "two", "three"]),
            [
                "For want of a one the two was lost.",
                "For want of a two the three was lost.",
                "And all for the want of a one.",
            ],
        )


if __name__ == "__main__":
    unittest.main()

